interface IState { handle(ctx: Session): void; }
class Connected implements IState { handle(ctx: Session) { ctx.send(); ctx.setState(new Disconnected()); } }
class Session { private state: IState; setState(s: IState) { this.state = s; } handle() { this.state.handle(this); } }

// Version A: centralized switch
class ConnectionA {
  state: 'disconnected' | 'connected' | 'connecting';
  send(data: string) {
    switch (this.state) {
      case 'connected': /* send */ break;
      default: throw new Error('not ready');
    }
  }
}

// Version B: per-state classes
interface ConnState { send(ctx: ConnectionB, data: string): void }
class ConnectedState implements ConnState { send(ctx: ConnectionB, data: string) { /* send */ } }
class ConnectionB { private state: ConnState; send(data: string) { this.state.send(this, data); } }
